export type Primitive = string | number | boolean | null | undefined | symbol | bigint;
export type Nullish = null | undefined;
export type Falsy = false | 0 | '' | null | undefined;
export type AnyFunction = (...args: unknown[]) => unknown;
export type AnyObject = Record<string, unknown>;
export type DeepPartial<T> = T extends object ? {
    [P in keyof T]?: DeepPartial<T[P]>;
} : T;
export type DeepRequired<T> = T extends object ? {
    [P in keyof T]-?: DeepRequired<T[P]>;
} : T;
export type DeepReadonly<T> = T extends object ? {
    readonly [P in keyof T]: DeepReadonly<T[P]>;
} : T;
export type Mutable<T> = {
    -readonly [P in keyof T]: T[P];
};
export type DeepMutable<T> = T extends object ? {
    -readonly [P in keyof T]: DeepMutable<T[P]>;
} : T;
export type KeysOfType<T, V> = {
    [K in keyof T]: T[K] extends V ? K : never;
}[keyof T];
export type OptionalKeys<T> = {
    [K in keyof T]-?: undefined extends T[K] ? K : never;
}[keyof T];
export type RequiredKeys<T> = {
    [K in keyof T]-?: undefined extends T[K] ? never : K;
}[keyof T];
export type PickByType<T, V> = {
    [K in keyof T as T[K] extends V ? K : never]: T[K];
};
export type OmitByType<T, V> = {
    [K in keyof T as T[K] extends V ? never : K]: T[K];
};
export type UnionToIntersection<U> = (U extends unknown ? (k: U) => void : never) extends (k: infer I) => void ? I : never;
export type Awaited<T> = T extends Promise<infer U> ? Awaited<U> : T;
export type MaybePromise<T> = T | Promise<T>;
export type MaybeArray<T> = T | T[];
export type ElementOf<T> = T extends (infer E)[] ? E : never;
export type Path<T, K extends keyof T = keyof T> = K extends string ? T[K] extends Record<string, unknown> ? `${K}` | `${K}.${Path<T[K]>}` : `${K}` : never;
export type PathValue<T, P extends string> = P extends `${infer K}.${infer Rest}` ? K extends keyof T ? PathValue<T[K], Rest> : never : P extends keyof T ? T[P] : never;
